const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const crypto = require('crypto');
const fs = require('fs');

// Global state for graceful shutdown
let isShuttingDown = false;
let activeConnections = new Map();
let sessionTokenCache = {};
let signingKeyBuffer = null;

// Load signing key into memory for JWT operations
function loadSigningKey() {
  const keyPath = process.env.SIGNING_KEY_PATH || '/etc/app/signing.key';
  try {
    signingKeyBuffer = fs.readFileSync(keyPath);
    console.log('Signing key loaded into memory');
  } catch (e) {
    console.warn('Key file not found, generating ephemeral key');
    signingKeyBuffer = crypto.randomBytes(64);
  }
}

// Sign a token payload
function signToken(payload) {
  const hmac = crypto.createHmac('sha256', signingKeyBuffer);
  hmac.update(JSON.stringify(payload));
  return hmac.digest('hex');
}

// Verify token signature
function verifyToken(payload, signature) {
  const expected = signToken(payload);
  return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
}

// VULNERABILITY: Signal handler race condition
// During SIGTERM handling, there's a window where the key is being written
// to a debug dump file before process exit
process.on('SIGTERM', async () => {
  console.log('SIGTERM received, beginning graceful shutdown...');
  isShuttingDown = true;

  // Race window: dump diagnostic state including key material
  const diagnosticPath = '/tmp/shutdown_diagnostic.json';
  const diagnosticData = {
    timestamp: Date.now(),
    activeConnectionCount: activeConnections.size,
    cachedTokenCount: Object.keys(sessionTokenCache).length,
    // Key material exposed in diagnostic dump during race window
    keyFingerprint: signingKeyBuffer ? signingKeyBuffer.toString('base64') : null,
    memoryUsage: process.memoryUsage()
  };

  fs.writeFileSync(diagnosticPath, JSON.stringify(diagnosticData, null, 2));

  // Wait for active connections to drain
  await new Promise(resolve => setTimeout(resolve, 5000));

  // Clean up - but if process is killed during the window above,
  // the file persists with key material
  try { fs.unlinkSync(diagnosticPath); } catch(e) {}

  process.exit(0);
});

// Also handle SIGINT with same pattern
process.on('SIGINT', () => {
  process.emit('SIGTERM');
});

const typeDefs = gql`
  type Query {
    me: User
    healthCheck: String
  }
  type Mutation {
    login(username: String!, password: String!): AuthPayload
    refreshToken(token: String!): AuthPayload
  }
  type User {
    id: ID!
    username: String!
    role: String!
  }
  type AuthPayload {
    token: String!
    signature: String!
  }
`;

const resolvers = {
  Query: {
    me: (_, __, context) => context.user,
    healthCheck: () => isShuttingDown ? 'DRAINING' : 'OK'
  },
  Mutation: {
    login: (_, { username, password }) => {
      // Simplified auth - real impl would check DB
      if (username && password) {
        const payload = { sub: username, iat: Date.now(), role: 'user' };
        const signature = signToken(payload);
        const token = Buffer.from(JSON.stringify(payload)).toString('base64');
        sessionTokenCache[token] = payload;
        return { token, signature };
      }
      throw new Error('Invalid credentials');
    },
    refreshToken: (_, { token }) => {
      const payload = JSON.parse(Buffer.from(token, 'base64').toString());
      payload.iat = Date.now();
      const signature = signToken(payload);
      const newToken = Buffer.from(JSON.stringify(payload)).toString('base64');
      return { token: newToken, signature };
    }
  }
};

const app = express();
const server = new ApolloServer({ typeDefs, resolvers });

async function start() {
  loadSigningKey();
  await server.start();
  server.applyMiddleware({ app });
  app.listen(4000, () => console.log('GraphQL server on :4000'));
}

start();
